const status=t=>'<span class="status '+String(t).toLowerCase().replaceAll("_","-")+'">'+esc(String(t).replaceAll("_"," "))+"</span>";
function startTrial(){const n=Date.now();localStorage.setItem(KEY,JSON.stringify({startedAt:n,expiresAt:n+DAYS*86400000,mode:"anonymous_trial"}));render()}
function closeModal(e){if(!e||e.target===e.currentTarget||!e.target.closest?.(".modal-card"))document.getElementById("modal")?.remove()}
function modal(title,body,wide=false){let x=document.getElementById("modal");if(!x){x=document.createElement("div");x.id="modal";document.body.appendChild(x)}x.innerHTML='<div class="modal-backdrop" onclick="closeModal(event)"><div class="modal-card '+(wide?"modal-wide":"")+'" onclick="event.stopPropagation()"><button class="modal-x" onclick="closeModal()">×</button><div class="modal-kicker">RT/RW–SID CONNECT · '+esc(modules[state.view]?.[0]||"WORKSPACE")+'</div><h3>'+esc(title)+'</h3>'+body+"</div></div>"}
async function submitSignIn(){const email=document.getElementById("auth-email")?.value.trim();if(!email||!sb)return;const r=await sb.auth.signInWithOtp({email,options:{emailRedirectTo:location.href}}),m=document.getElementById("auth-msg");m.textContent=r.error?r.error.message:"Link akses telah dikirim. Periksa inbox Anda.";m.className="modal-msg "+(r.error?"error":"success")}
function signIn(){if(!sb){modal("Konfigurasi belum siap","<p>Supabase belum terhubung. Trial tetap dapat digunakan.</p>");return}modal("Masuk ke workspace",'<p>Gunakan email untuk menerima link akses tanpa password.</p><label>Email</label><input id="auth-email" type="email" autocomplete="email" placeholder="nama@contoh.id"><button class="primary" onclick="submitSignIn()">Kirim Link Akses</button><div id="auth-msg" class="modal-msg"></div>')}
async function signOut(){if(sb)await sb.auth.signOut();localStorage.removeItem(KEY);location.reload()}
function landing(){document.getElementById("landing").innerHTML='<div class="landing"><header><div class="brand"><b>RS</b><span>RT/RW–SID CONNECT<small>COMMUNITY · VILLAGE · SMART VILLAGE OS</small></span></div><span class="pilot">FREE-FIRST PILOT · v2.0</span></header><main><section><div class="eyebrow">DIGITAL OPERATING PLATFORM</div><h1>Satu operating system untuk <em>komunitas & desa.</em></h1><p>Hubungkan Warga, RT, RW, Desa, Smart Village, Jolie Business OS, GPFFE, GIS dan governance dalam satu core data platform.</p><div class="actions"><button onclick="signIn()">Sign In</button><button class="ghost" onclick="startTrial()">Coba Trial 7 Hari</button></div><div class="trust"><span>✓ Tanpa kartu kredit</span><span>✓ Trial anonim</span><span>✓ Privacy by design</span></div></section><div class="landing-preview"><div class="preview-chrome"><span>● ● ●</span><b>community-data-os</b><i>TRIAL</i></div><div class="preview-shell"><aside><strong>RS</strong><div class="pnav active">⌂</div><div class="pnav">♙</div><div class="pnav">▣</div><div class="pnav">◈</div></aside><article><div class="preview-head"><small>COMMAND CENTER</small><b>Operational Overview</b></div><div class="preview-kpis"><div><strong>1,284</strong><small>Warga</small></div><div><strong>326</strong><small>KK</small></div><div><strong>48</strong><small>Layanan</small></div></div><div class="preview-chart"><span style="height:42%"></span><span style="height:60%"></span><span style="height:50%"></span><span style="height:76%"></span><span style="height:68%"></span><span style="height:90%"></span><span style="height:82%"></span></div><div class="preview-row"><span>Progressive verification</span><b>86%</b></div></article></div></div></main><footer>RT/RW–SID CONNECT v2.0 · Community, Village & Smart Village Digital Operating Platform</footer></div>'}
function nav(){let h="";for(const g of groups){const es=Object.entries(modules).filter(([,m])=>m[1]===g);if(!es.length)continue;h+='<div class="nav-group"><small>'+g+"</small>";for(const [k,m] of es){h+='<div class="nav-module"><button class="'+(state.view===k?"active":"")+'" data-nav-module="'+esc(k)+'" data-nav-sub="'+esc(m[2][0][0])+'"><span class="nav-icon">'+(icons[k]||"•")+"</span>"+esc(m[0])+"<b>›</b></button>";if(state.view===k)h+='<div class="nav-submenu">'+m[2].map(s=>'<button class="'+(state.sub===s[0]?"active":"")+'" data-nav-module="'+esc(k)+'" data-nav-sub="'+esc(s[0])+'">'+esc(s[1])+"</button>").join("")+"</div>";h+="</div>"}h+="</div>"}return h}
document.addEventListener("click",function(e){const el=e.target.closest("[data-nav-module][data-nav-sub]");if(!el)return;e.preventDefault();e.stopPropagation();go(el.dataset.navModule,el.dataset.navSub);});
document.addEventListener("click",function(e){const el=e.target.closest("[data-live-action][data-live-id]");if(!el)return;e.preventDefault();e.stopPropagation();const id=el.dataset.liveId;if(el.dataset.liveAction==="view")openLiveRecord(id);if(el.dataset.liveAction==="update")openLiveUpdate(id);});
function go(v,s,push=true){if(push&&(state.view!==v||state.sub!==s))state.history.push([state.view,state.sub]);state.forward=[];state.view=v;state.sub=s;state.selected.clear();render()}
function back(){const h=state.history.pop();if(!h){toast("Tidak ada halaman sebelumnya");return}state.forward.push([state.view,state.sub]);state.view=h[0];state.sub=h[1];render()}
function next(){const h=state.forward.pop();if(!h){const idx=modules[state.view][2].findIndex(x=>x[0]===state.sub),a=modules[state.view][2][idx+1];if(a){state.history.push([state.view,state.sub]);state.sub=a[0];render()}else toast("Sudah di submenu terakhir");return}state.history.push([state.view,state.sub]);state.view=h[0];state.sub=h[1];render()}
function toast(msg){let x=document.getElementById("toast");if(!x){x=document.createElement("div");x.id="toast";document.body.appendChild(x)}x.textContent=msg;x.classList.add("show");clearTimeout(window.__toast);window.__toast=setTimeout(()=>x.classList.remove("show"),2200)}
